<script>
export default {
  data(){
    return{
      clickable: false,
      show: false
    }
  },
  methods: {

  doLoad(){

    document.getElementById('potion1').style.opacity = 1;
    // console.log(document.getElementById(('potion')))
    console.log('load')
    setTimeout(() => {this.clickable = true}, 1000)
  },
    doStart(){
    if (!this.clickable){
      return false;
    }
    this.clickable = false;
    document.getElementById('potion1').style.opacity = 0;
    setTimeout(() => {this.$router.replace('/potion')}, 1000)
    }
  },
  created() {

  },
  mounted() {
    this.doLoad();
  }
}
</script>

<template>
<div class="clickpotion" >
  <div class="potion_outer">
    <div class="potion_inner" id="potion1" @click="doStart">
      <div class="story">
        <p>{{$t('message.story_1')}}</p>
        <p>{{$t('message.story_2')}}</p>
        <p>{{$t('message.story_3')}}</p>
      </div>
      <p class="continue">{{$t('message.story_4')}}</p>
    </div>

  </div>
</div>
</template>

<style scoped lang="scss">
@media (orientation: portrait){
  .potion_outer {
    width: 100% !important;
    height: auto !important;
  }
  .potion_inner{
    .story{
      font-size: 4vw !important;
    }
    .continue{
      font-size: 6vw !important;
    }
  }
}
.clickpotion {
  width: 100%;
  height: 100vh;
  background-color: #ab47bc;
  overflow: hidden;
  user-select: none;
  display: flex;
  align-items: center;
  justify-content: center;
  .potion_outer {
    aspect-ratio: 1259/1575;
    width: auto;
    height: 100%;
    margin: 0 auto;
    background-color: black;
    position: relative;
    cursor: pointer;
    .blocker {
      position: absolute;
      width: 100%;
      height: 100vh;
      top: 0;
      left: 0;
      z-index: 96;
    }
  }
  .potion_inner {
    width: auto;
    height: 100%;
    position: relative;
    background-color: black;
    transition: opacity 1000ms;
    opacity: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    .story{
      width: 90%;
      font-size: 2.8vh;
      text-align: center;
    }
    *{
      color: white;
      font-family: "Cherry Bomb One", sans-serif;
    }
    .continue{
      width: 90%;
      text-align: center;
      font-size: 3.8vh;
      animation: flashing 3000ms infinite linear;
    }
  }
}
@keyframes flashing {
  0% {
    opacity: 0;
  }
  50%{
    opacity: 100%;
  }
  100%{
    opacity: 0;
  }
}
</style>
